using System.Net;
using System.Text.Json;
using SmartRail.Host.Health;
using SmartRail.Host.IntegrationTests.Infrastructure;

namespace SmartRail.Host.IntegrationTests.Seeding;

/// <summary>
/// Seeding is a start-up path against a real database, so it is checked here rather than by a unit
/// test: the second start is what proves idempotency, and only the database can prove the counts
/// (design D9, seed-data spec). The journeys are generated by a hosted service after
/// <c>app.Run()</c>, so the timetable assertion polls instead of assuming they already exist.
/// </summary>
[Collection(PostgresCollection.Name)]
public sealed class NetworkSeedTests(PostgresFixture postgres)
{
    /// <summary>The railway's default time zone, which decides what "today" means to the endpoint.</summary>
    private const string RailwayTimeZoneId = "Asia/Colombo";

    private static readonly TimeSpan JourneyPollTimeout = TimeSpan.FromSeconds(10);

    [Fact]
    public async Task Starting_twice_leaves_one_set_of_network_and_timetable_rows()
    {
        await StartAsync();
        await StartAsync();

        Assert.Equal(9, await CountAsync("network.stations"));
        Assert.Equal(11, await CountAsync("network.platforms"));
        Assert.Equal(2, await CountAsync("network.lines"));
        Assert.Equal(52, await CountAsync("network.services"));
        Assert.Equal(260, await CountAsync("network.service_stops"));
    }

    [Fact]
    public async Task The_seeded_network_and_journeys_are_readable_through_the_public_api()
    {
        await StartAsync();
        await StartAsync();

        using var factory = new SmartRailApiFactory(postgres.ConnectionString);
        using var client = factory.CreateApiClient();

        var stations = await GetArrayAsync(client, "/api/v1/network/stations");
        Assert.Equal(9, stations.GetArrayLength());
        Assert.Single(stations.EnumerateArray(), station => station.GetProperty("isInterchange").GetBoolean());

        var interchange = stations.EnumerateArray().Single(station => station.GetProperty("isInterchange").GetBoolean());
        Assert.Equal(2, interchange.GetProperty("lines").GetArrayLength());

        var lines = await GetArrayAsync(client, "/api/v1/network/lines");
        Assert.Equal(2, lines.GetArrayLength());
        Assert.All(lines.EnumerateArray(), line => Assert.Equal(5, line.GetProperty("stations").GetArrayLength()));

        var journeys = await PollJourneysAsync(client, TodayInRailwayTime());
        Assert.Equal(52, journeys.GetArrayLength());
    }

    private async Task StartAsync()
    {
        using var factory = new SmartRailApiFactory(postgres.ConnectionString);
        using var client = factory.CreateApiClient();
        using var response = await client.GetAsync(HealthEndpoints.ReadyPath);

        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
    }

    private async Task<long> CountAsync(string table)
    {
        var counts = await postgres.QueryAsync($"SELECT count(*) FROM {table}", reader => reader.GetInt64(0));

        return Assert.Single(counts);
    }

    private static async Task<JsonElement> GetArrayAsync(HttpClient client, string path)
    {
        using var response = await client.GetAsync(path);
        Assert.Equal(HttpStatusCode.OK, response.StatusCode);

        using var document = JsonDocument.Parse(await response.Content.ReadAsStringAsync());
        Assert.Equal(JsonValueKind.Array, document.RootElement.ValueKind);

        return document.RootElement.Clone();
    }

    /// <summary>
    /// Generation runs as a hosted service, so the board can be empty for a moment after readiness
    /// answers. Polling for the expected count is what proves a second start added no journeys.
    /// </summary>
    private static async Task<JsonElement> PollJourneysAsync(HttpClient client, DateOnly date)
    {
        var deadline = DateTimeOffset.UtcNow + JourneyPollTimeout;
        JsonElement journeys = default;

        while (true)
        {
            using var response = await client.GetAsync($"/api/v1/timetable/journeys?date={date:yyyy-MM-dd}");
            Assert.Equal(HttpStatusCode.OK, response.StatusCode);

            using var document = JsonDocument.Parse(await response.Content.ReadAsStringAsync());
            Assert.Equal(JsonValueKind.Array, document.RootElement.ValueKind);

            journeys = document.RootElement.Clone();

            if (journeys.GetArrayLength() == 52 || DateTimeOffset.UtcNow >= deadline)
            {
                return journeys;
            }

            await Task.Delay(TimeSpan.FromMilliseconds(200));
        }
    }

    private static DateOnly TodayInRailwayTime() => DateOnly.FromDateTime(
        TimeZoneInfo.ConvertTime(DateTimeOffset.UtcNow, TimeZoneInfo.FindSystemTimeZoneById(RailwayTimeZoneId)).DateTime);
}
